ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';fit=json.loads((DOC/'bellybot_fit.json').read_text());val=json.loads((DOC/'validation.json').read_text())
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
