a=axs[0];s=fit['base_yaw_sweep'];a.plot([r['degrees'] for r in s],[r['side_wall_m']*1000 for r in s],color='#168b78',lw=2.5);a.axhline(0,color='#bc4e36',lw=1.5);a.axhline(25,color='#7d8467',ls='--',lw=1);a.set(xlabel='Chassis yaw (degrees)',ylabel='Minimum liner clearance (mm)',title='Whole-body turn: early interference');a.text(30,5,'Collision below this line',color='#bc4e36',fontsize=9);a.grid(alpha=.18)
yaws=sorted(set(r['yaw_deg'] for r in fit['upper_workspace']));reach=sorted(set(r['reach_m'] for r in fit['upper_workspace']));Z=np.zeros((len(reach),len(yaws)))
for r in fit['upper_workspace']:Z[reach.index(r['reach_m']),yaws.index(r['yaw_deg'])]=2 if r['operational_margin_pass'] else (1 if r['enclosure_pass'] else 0)
